import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DDY-poMm.js";const c=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq/index.md","filePath":"faq/index.md","lastUpdated":1790683574000}'),s={name:"faq/index.md"};function r(i,e,h,d,l,u){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Every question on this page is one that <strong>has actually come up</strong>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="i-changed-a-setting-in-the-admin-console-but-nothing-changed-on-the-user-side" tabindex="-1">I changed a setting in the admin console, but nothing changed on the user side? <a class="header-anchor" href="#i-changed-a-setting-in-the-admin-console-but-nothing-changed-on-the-user-side" aria-label="Permalink to &quot;I changed a setting in the admin console, but nothing changed on the user side?&quot;">​</a></h3><p>User-side configuration is <strong>fetched once at startup</strong>. After operators make a change:</p><ul><li><strong>App</strong>: users must <strong>fully quit the app and reopen it</strong> (sending it to the background doesn&#39;t count); the new configuration arrives on the next launch</li><li><strong>Web (PC / H5)</strong>: just refresh the page</li></ul><h3 id="the-setting-is-filled-in-but-the-user-side-shows-no-data" tabindex="-1">The setting is filled in, but the user side shows &quot;No data&quot;? <a class="header-anchor" href="#the-setting-is-filled-in-but-the-user-side-shows-no-data" aria-label="Permalink to &quot;The setting is filled in, but the user side shows &quot;No data&quot;?&quot;">​</a></h3><p>First check whether the item&#39;s <strong>switch is on</strong>. In list-type settings (bottom bar, home shortcuts, side menu, download links, etc.), disabled items are not sent to the user side; if the whole group is off, the user side is empty.</p><h3 id="links-in-the-download-center-do-nothing-when-tapped" tabindex="-1">Links in the download center do nothing when tapped? <a class="header-anchor" href="#links-in-the-download-center-do-nothing-when-tapped" aria-label="Permalink to &quot;Links in the download center do nothing when tapped?&quot;">​</a></h3><p>Check that the download URL <strong>includes the <code>http://</code> or <code>https://</code> prefix</strong>. A bare domain (e.g. <code>example.com</code>) is treated as a relative in-site path on some clients, so tapping does nothing.</p><h3 id="the-white-paper-won-t-open-shows-a-blank-page" tabindex="-1">The white paper won&#39;t open / shows a blank page? <a class="header-anchor" href="#the-white-paper-won-t-open-shows-a-blank-page" aria-label="Permalink to &quot;The white paper won&#39;t open / shows a blank page?&quot;">​</a></h3><p>Configure the white paper as a <strong>web page or PDF</strong>. If it&#39;s a <code>.doc</code> file, the user side&#39;s embedded browser can&#39;t render it, and it shows up blank.</p><h2 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to &quot;App&quot;">​</a></h2><h3 id="a-user-can-t-install-the-app-—-app-not-installed" tabindex="-1">A user can&#39;t install the app — &quot;App not installed&quot;? <a class="header-anchor" href="#a-user-can-t-install-the-app-—-app-not-installed" aria-label="Permalink to &quot;A user can&#39;t install the app — &quot;App not installed&quot;?&quot;">​</a></h3><p>Most likely the phone has <strong>an app with the same name from a different source</strong> (e.g. an old package downloaded from another channel). Mismatched signatures prevent installing over it; uninstall the old version first.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Uninstalling clears local data, and the user will need to log in again.</p></div><h3 id="users-don-t-get-the-update-prompt" tabindex="-1">Users don&#39;t get the update prompt? <a class="header-anchor" href="#users-don-t-get-the-update-prompt" aria-label="Permalink to &quot;Users don&#39;t get the update prompt?&quot;">​</a></h3><p>Check in order:</p><ol><li>Is the <strong>master switch</strong> under &quot;Basic Configuration → App Version Update&quot; on?</li><li>Is the &quot;Latest version code&quot; <strong>greater than</strong> the version the user has installed?</li><li>Has the user already tapped &quot;Later&quot; today? After that, the prompt won&#39;t show again that day</li><li>Has the user <strong>fully quit and reopened</strong> the app?</li></ol><h3 id="a-user-tapped-update-but-the-download-failed" tabindex="-1">A user tapped update, but the download failed? <a class="header-anchor" href="#a-user-tapped-update-but-the-download-failed" aria-label="Permalink to &quot;A user tapped update, but the download failed?&quot;">​</a></h3><p>Open the configured download URL in a browser yourself and confirm it downloads. If the link itself doesn&#39;t open, the package hasn&#39;t been uploaded yet or the URL is wrong.</p><h2 id="funds" tabindex="-1">Funds <a class="header-anchor" href="#funds" aria-label="Permalink to &quot;Funds&quot;">​</a></h2><h3 id="a-user-says-their-deposit-hasn-t-arrived" tabindex="-1">A user says their deposit hasn&#39;t arrived? <a class="header-anchor" href="#a-user-says-their-deposit-hasn-t-arrived" aria-label="Permalink to &quot;A user says their deposit hasn&#39;t arrived?&quot;">​</a></h3><ol><li>First confirm that <strong>the chain (network) the user transferred on matches the selected coin</strong>. Assets sent on the wrong chain usually cannot be recovered</li><li>Search &quot;Deposit Records&quot; in the admin console by UID for a matching record</li><li>On-chain confirmation takes time, and confirmation speeds vary widely between chains</li></ol><h3 id="a-user-says-their-balance-doesn-t-add-up" tabindex="-1">A user says their balance doesn&#39;t add up? <a class="header-anchor" href="#a-user-says-their-balance-doesn-t-add-up" aria-label="Permalink to &quot;A user says their balance doesn&#39;t add up?&quot;">​</a></h3><p>Pull that user&#39;s <strong>complete ledger</strong> and check it entry by entry. Every entry records the amount changed and the balance before and after, so you can pinpoint exactly which entry introduced the difference.</p><div class="danger custom-block"><p class="custom-block-title">Don&#39;t &quot;smooth it over&quot; with an adjustment</p><p>When something doesn&#39;t add up, find the cause before acting. Simply adjusting the balance to a number that &quot;looks right&quot; makes later reconciliation harder.</p></div><h3 id="can-a-withdrawal-be-recalled-after-approval" tabindex="-1">Can a withdrawal be recalled after approval? <a class="header-anchor" href="#can-a-withdrawal-be-recalled-after-approval" aria-label="Permalink to &quot;Can a withdrawal be recalled after approval?&quot;">​</a></h3><p><strong>No.</strong> Approval sends a real on-chain transfer, which cannot be recalled once sent. Always check the address, network and amount when reviewing.</p><h2 id="customer-service" tabindex="-1">Customer service <a class="header-anchor" href="#customer-service" aria-label="Permalink to &quot;Customer service&quot;">​</a></h2><h3 id="a-user-sent-a-message-in-the-app-but-nothing-appears-in-the-support-group" tabindex="-1">A user sent a message in the app, but nothing appears in the support group? <a class="header-anchor" href="#a-user-sent-a-message-in-the-app-but-nothing-appears-in-the-support-group" aria-label="Permalink to &quot;A user sent a message in the app, but nothing appears in the support group?&quot;">​</a></h3><p>Usually the group is misconfigured: the &quot;Support group ID&quot; must be <strong>a supergroup with Topics enabled</strong>, not a private chat; the bot must be a group administrator with <strong>&quot;Manage Topics&quot; explicitly ticked</strong>. For the full troubleshooting order, see <a href="/CoinExchange/guide/customer-service#faq">Customer Service</a>.</p><h3 id="an-agent-replied-in-telegram-but-the-user-doesn-t-receive-it-in-the-app" tabindex="-1">An agent replied in Telegram, but the user doesn&#39;t receive it in the app? <a class="header-anchor" href="#an-agent-replied-in-telegram-but-the-user-doesn-t-receive-it-in-the-app" aria-label="Permalink to &quot;An agent replied in Telegram, but the user doesn&#39;t receive it in the app?&quot;">​</a></h3><p>Messages get in but don&#39;t come back, so the problem is the callback: are both the <strong>callback URL and callback secret</strong> under &quot;Third-Party Configuration → Live chat&quot; filled in, and was it saved again afterwards? If either is missing, the page still says it saved successfully, but the callback is not registered.</p><h3 id="an-agent-replied-with-a-voice-message-but-the-user-didn-t-get-it" tabindex="-1">An agent replied with a voice message, but the user didn&#39;t get it? <a class="header-anchor" href="#an-agent-replied-with-a-voice-message-but-the-user-didn-t-get-it" aria-label="Permalink to &quot;An agent replied with a voice message, but the user didn&#39;t get it?&quot;">​</a></h3><p>Only <strong>text, emoji and images</strong> are forwarded for now; voice messages and files are not delivered to the app.</p><h2 id="user-experience" tabindex="-1">User experience <a class="header-anchor" href="#user-experience" aria-label="Permalink to &quot;User experience&quot;">​</a></h2><h3 id="a-user-reports-the-countdown-doesn-t-match-the-actual-settlement-time" tabindex="-1">A user reports the countdown doesn&#39;t match the actual settlement time? <a class="header-anchor" href="#a-user-reports-the-countdown-doesn-t-match-the-actual-settlement-time" aria-label="Permalink to &quot;A user reports the countdown doesn&#39;t match the actual settlement time?&quot;">​</a></h3><p>Seconds-contract countdowns are based solely on the <strong>server&#39;s fixing time</strong>, and the client calibrates its clock. If the phone&#39;s system time is far off, there may be a brief visual difference, but actual settlement follows the server.</p><h3 id="languages-are-incomplete-some-text-is-still-in-chinese" tabindex="-1">Languages are incomplete / some text is still in Chinese? <a class="header-anchor" href="#languages-are-incomplete-some-text-is-still-in-chinese" aria-label="Permalink to &quot;Languages are incomplete / some text is still in Chinese?&quot;">​</a></h3><p>The user side supports 7 languages, controlled by the language dictionary in the admin console. If a new feature&#39;s text isn&#39;t translated, report it to your technical team to add it to the language pack.</p><hr><div class="tip custom-block"><p class="custom-block-title">Didn&#39;t find an answer?</p><p>If the issue involves a funds discrepancy, an abnormal order or a system error, please provide the <strong>user UID, time of occurrence, amount involved and app version</strong> (at the bottom of the &quot;Me&quot; page), and contact technical support.</p></div>',43)])])}const g=t(s,[["render",r]]);export{c as __pageData,g as default};
